const TLS_PASS_TIMEOUT_MS = 4 * 60_000;

/**
 * Enqueue the post-cutover certificate pass for migrations whose DNS may have
 * moved since they finished.
 *
 * WHY THIS EXISTS. `runPostCutoverTls` was written for exactly this job and had
 * exactly one enqueue line — **inside a comment**. So it was dead code, and a
 * customer who migrated, then pointed their DNS a day later, never got the
 * certificate that could not be issued during the run: their first HTTPS visit
 * was a browser warning, forever.
 *
 * That was bad on its own. It became worse on 2026-07-26, when the migration
 * report's cutover instructions were rewritten to tell the customer, in plain
 * words, that "Nxeon issues the certificate automatically within about 30 minutes
 * of the change, and nothing else is needed." That sentence was false the moment
 * it shipped. `sslSweep` does NOT cover this case — it walks `db.sslCertificate`
 * rows, and a migration never writes one. A promise the product does not keep is
 * the same defect as a success this engine did not verify, so the promise is made
 * true here rather than walked back in the copy.
 *
 * Safe to run repeatedly by construction: the pass copies nothing, never touches
 * the source server, never rewrites `Migration.status`, and certbot's
 * `--keep-until-expiring` makes an already-certified domain a no-op.
 */
export async function postCutoverTlsSweep(): Promise<void> {
  const since = new Date(Date.now() - TLS_WATCH_DAYS * 86_400_000);
  const runningServerIds = (
    await db.server.findMany({ where: { status: "RUNNING" }, select: { id: true } })
  ).map((s) => s.id);
  if (!runningServerIds.length) return;

  const candidates = await db.migration.findMany({
    where: {
      status: { in: ["DONE", "COMPLETED_WITH_ISSUES"] },
      finishedAt: { gte: since },
      // SSH is the first thing this pass does. A server that is not running
      // cannot answer, and the attempt would occupy the strictly-serial worker
      // until the connection times out. `Migration.serverId` is a bare column
      // with no Prisma relation, so the running set is resolved separately.
      serverId: { in: runningServerIds },
    },
    select: { id: true, items: true, serverId: true },
    orderBy: { finishedAt: "desc" },
    take: 50,
  });

  // ONE pass per target server, not per migration. A customer who retried a
  // migration three times has three rows pointing at the same box; certifying it
  // once certifies it for all of them, and the first live run queued four
  // redundant SSH sessions for a single server. Newest first, since that run's
  // published site config is the one on disk.
  const seenServers = new Set<string>();

  for (const m of candidates) {
    // Already fully certified — a previous pass found nothing outstanding.
    if ((m.items as { tlsSettled?: boolean } | null)?.tlsSettled) continue;
    if (seenServers.has(m.serverId)) continue;
    seenServers.add(m.serverId);

    // Don't stack attempts. A job still queued, or one tried recently, means the
    // answer is already on its way; certbot rate limits are real and shared.
    const recent = await db.job.findFirst({
